CREATE TABLE "ProfessionalCareConsent" (id TEXT PRIMARY KEY, "professionalId" TEXT NOT NULL REFERENCES professional_profiles(id) ON DELETE RESTRICT, "patientId" TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, active BOOLEAN NOT NULL DEFAULT true, "grantedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "revokedAt" TIMESTAMP(3), UNIQUE ("professionalId", "patientId"));
CREATE TABLE "ProfessionalCarePlan" (id TEXT PRIMARY KEY, "professionalId" TEXT NOT NULL REFERENCES professional_profiles(id) ON DELETE RESTRICT, "patientId" TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, kind TEXT NOT NULL, title TEXT NOT NULL, draft JSONB NOT NULL, revision INTEGER NOT NULL DEFAULT 1, "publishedVersion" INTEGER, "archivedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CHECK (kind IN ('NUTRITION','SUPPORT')), CHECK (revision > 0));
CREATE INDEX "ProfessionalCarePlan_professionalId_patientId_idx" ON "ProfessionalCarePlan" ("professionalId", "patientId");
CREATE INDEX "ProfessionalCarePlan_patientId_publishedVersion_idx" ON "ProfessionalCarePlan" ("patientId", "publishedVersion");
CREATE TABLE "ProfessionalCareVersion" (id TEXT PRIMARY KEY, "planId" TEXT NOT NULL REFERENCES "ProfessionalCarePlan"(id) ON DELETE RESTRICT, number INTEGER NOT NULL CHECK (number > 0), content JSONB NOT NULL, "publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("planId", number));
CREATE TABLE "ProfessionalCareFeedback" (id TEXT PRIMARY KEY, "planId" TEXT NOT NULL REFERENCES "ProfessionalCarePlan"(id) ON DELETE RESTRICT, version INTEGER NOT NULL, message TEXT NOT NULL, progress TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ProfessionalCareFeedback_planId_createdAt_idx" ON "ProfessionalCareFeedback" ("planId", "createdAt");
CREATE TABLE "ProfessionalCareNote" (id TEXT PRIMARY KEY, "planId" TEXT NOT NULL REFERENCES "ProfessionalCarePlan"(id) ON DELETE RESTRICT, text TEXT NOT NULL, "followUpAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ProfessionalCareNote_planId_createdAt_idx" ON "ProfessionalCareNote" ("planId", "createdAt");
CREATE TABLE "ProfessionalCareTemplate" (id TEXT PRIMARY KEY, "professionalId" TEXT NOT NULL REFERENCES professional_profiles(id) ON DELETE RESTRICT, kind TEXT NOT NULL CHECK (kind IN ('NUTRITION','SUPPORT')), name TEXT NOT NULL, content JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ProfessionalCareTemplate_professionalId_idx" ON "ProfessionalCareTemplate" ("professionalId");
CREATE FUNCTION sabi_immutable_care_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Published care versions and session notes are immutable'; END; $$;
CREATE TRIGGER "care_version_immutable" BEFORE UPDATE OR DELETE ON "ProfessionalCareVersion" FOR EACH ROW EXECUTE FUNCTION sabi_immutable_care_record();
CREATE TRIGGER "care_note_immutable" BEFORE UPDATE OR DELETE ON "ProfessionalCareNote" FOR EACH ROW EXECUTE FUNCTION sabi_immutable_care_record();
